<?php

namespace App\Services;

use App\Models\SiteSetting;
use App\Models\TrainingRoom;
use App\Models\User;
use App\Services\Saber\ArabicMatch;
use Illuminate\Support\Arr;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Str;

/**
 * The centre's wayfinding map (docs/wayfinding.md): the floor plans with their walkable corridors and places (generated by
 * scripts/wayfinding/build_map.py into resources/wayfinding/centre-map.json), joined with what the administrator manages: which
 * training room is which place on the map (matched by name and number until someone says otherwise), the doors that sit elsewhere, the
 * entrances, the "you are here" signs, and where the centre is for the walk to it. Kept in site settings, so it needs no migration.
 */
class Wayfinding
{
    public const KEY = 'wayfinding';

    private const CACHE = 'site.wayfinding';

    /** The generated map (floors, corridors, places, stairs and lifts, default entrances). */
    public function map(): array
    {
        static $map = null;

        return $map ??= json_decode((string) file_get_contents(resource_path('wayfinding/centre-map.json')), true);
    }

    /** What the administrator set. */
    public function settings(): array
    {
        $stored = SiteSetting::find(self::KEY)?->value ?? [];

        return [
            'rooms' => is_array($stored['rooms'] ?? null) ? $stored['rooms'] : [],
            'entrances' => is_array($stored['entrances'] ?? null) ? $stored['entrances'] : null,
            'signs' => is_array($stored['signs'] ?? null) ? $stored['signs'] : [],
            'centre' => is_array($stored['centre'] ?? null) ? $stored['centre'] : null,
        ];
    }

    /** Everything a visitor's phone needs, cached for a minute (the public endpoint and the app read this). */
    public function payload(): array
    {
        return Cache::remember(self::CACHE, 60, fn () => $this->build());
    }

    public function build(bool $admin = false): array
    {
        $map = $this->map();
        $s = $this->settings();
        $places = collect($map['places'])->keyBy('id');
        $entrances = $s['entrances'] ?? $map['entrances'];
        $rooms = [];
        $auto = $this->autoMatches();
        foreach (TrainingRoom::query()->when(! $admin, fn ($q) => $q->where('status', '!=', 'inactive'))->orderBy('name_ar')->get(['id', 'name_ar', 'name_en', 'code', 'capacity', 'room_type', 'status', 'building', 'floor', 'latitude', 'longitude']) as $room) {
            $set = $s['rooms'][$room->id] ?? [];
            $placeId = array_key_exists('place', $set) ? $set['place'] : ($auto[$room->id] ?? null);
            $place = $placeId ? $places->get($placeId) : null;
            if (! empty($set['hidden']) && ! $admin) {
                continue;
            }
            $door = isset($set['door']) && $place ? $set['door'] : ($place['door'] ?? null);
            $rooms[] = [
                'id' => $room->id, 'name_ar' => $room->name_ar, 'name_en' => $room->name_en ?: $room->name_ar, 'code' => $room->code,
                'capacity' => $room->capacity, 'type' => $room->room_type, 'active' => $room->status === 'active',
                'place' => $place['id'] ?? null, 'floor' => $place['floor'] ?? null, 'door' => $door,
                'auto' => $place && ! array_key_exists('place', $set),
                // Rooms that are not at the centre: the walk there is outdoors, to their own coordinates.
                'latitude' => $room->latitude ? (float) $room->latitude : null, 'longitude' => $room->longitude ? (float) $room->longitude : null,
            ] + ($admin ? ['hidden' => ! empty($set['hidden']), 'custom_door' => isset($set['door'])] : []);
        }

        return [
            'map' => Arr::except($map, ['entrances']),
            'entrances' => array_values($entrances),
            'signs' => array_values($s['signs']),
            'rooms' => $rooms,
            'centre' => $s['centre'] ?? $this->defaultCentre(),
        ];
    }

    /**
     * Rooms the map recognises by their name: «قاعة 14» / «Training Room 14» is room 14 of the plans, «معمل الحاسب 2» computer lab 2,
     * «المكتبة» the library. Only one room per place, and only when the name leaves no doubt.
     *
     * @return array<string, string> room id → place id
     */
    public function autoMatches(): array
    {
        $places = $this->map()['places'];
        $taken = collect($this->settings()['rooms'])->pluck('place')->filter()->all();
        $out = [];
        $claimed = [];
        foreach (TrainingRoom::query()->where('status', '!=', 'inactive')->orderBy('created_at')->get(['id', 'name_ar', 'name_en']) as $room) {
            $place = $this->matchName($room->name_ar, $places) ?? $this->matchName($room->name_en, $places);
            if (! $place || in_array($place, $taken, true)) {
                continue;
            }
            if (isset($claimed[$place])) {
                unset($out[$claimed[$place]]);     // two rooms claim one place: neither is matched, the administrator decides
                $claimed[$place] = null;

                continue;
            }
            if (array_key_exists($place, $claimed)) {
                continue;
            }
            $claimed[$place] = $room->id;
            $out[$room->id] = $place;
        }

        return $out;
    }

    public function matchName(?string $name, array $places): ?string
    {
        $key = ArabicMatch::roomKey($name);
        if ($key === '') {
            return null;
        }
        if (preg_match('/(\d+)/', $key, $m)) {
            $number = (string) (int) $m[1];
            // The number must be the room's whole identity: «قاعة 14», «قاعة التدريب 14», «Computer Lab 2» — not «قاعة أ-١» (hall A1).
            $generic = ['قاعه', 'قاعات', 'تدريب', 'تدريبيه', 'تدريبي', 'معمل', 'مختبر', 'حاسب', 'حاسوب', 'الي', 'كمبيوتر', 'رقم', 'room', 'training', 'hall', 'lab', 'computer', 'pc', 'no'];
            $rest = implode(' ', array_filter(explode(' ', $key), fn ($w) => $w !== '' && ! ctype_digit($w) && ! in_array($w, $generic, true)));
            if ($rest !== '') {
                return null;
            }
            $computer = preg_match('/حاسب|حاسوب|كمبيوتر|computer|pc lab/u', $key) === 1;
            $meeting = preg_match('/اجتماع|meeting/u', $key) === 1;
            if (! $meeting) {
                foreach ($places as $p) {
                    if ($p['number'] === $number && ($computer ? $p['kind'] === 'lab' : $p['kind'] === 'train')) {
                        return $p['id'];
                    }
                }
            }

            return null;
        }
        foreach ($places as $p) {
            if (in_array($p['kind'], ['wc'], true)) {
                continue;
            }
            foreach ([$p['ar'], $p['en']] as $label) {
                $l = ArabicMatch::roomKey($label);
                if ($l === $key || ArabicMatch::roomKey(preg_replace('/^(قاعة|قاعه)\s+/u', '', $label)) === $key) {
                    return $p['id'];
                }
            }
        }

        return null;
    }

    /** The centre's coordinates for the walk to the building: what the administrator set, else the rooms' most common point. */
    private function defaultCentre(): ?array
    {
        $point = TrainingRoom::query()->whereNotNull('latitude')->whereNotNull('longitude')->selectRaw('latitude, longitude, count(*) as n')
            ->groupBy('latitude', 'longitude')->orderByDesc('n')->first();

        return $point ? ['lat' => (float) $point->latitude, 'lng' => (float) $point->longitude] : null;
    }

    /** Saves the entrances, the signs and the centre's coordinates. */
    public function update(array $input, User $by): array
    {
        $stored = SiteSetting::find(self::KEY)?->value ?? [];
        $floors = collect($this->map()['floors'])->pluck('id')->all();
        $clean = fn (array $list, string $prefix) => collect($list)->take(60)->map(fn ($e) => [
            'id' => preg_replace('/[^a-z0-9-]/', '', Str::lower((string) ($e['id'] ?? ''))) ?: $prefix.'-'.Str::lower(Str::random(6)),
            'floor' => in_array($e['floor'] ?? null, $floors, true) ? $e['floor'] : 'ground',
            'ar' => Str::limit(strip_tags((string) ($e['ar'] ?? '')), 120, ''), 'en' => Str::limit(strip_tags((string) ($e['en'] ?? '')), 120, ''),
            'at' => $this->point($e['at'] ?? null),
        ])->filter(fn ($e) => $e['at'] && $e['ar'] !== '')->values()->all();

        if (array_key_exists('entrances', $input)) {
            $stored['entrances'] = $input['entrances'] === null ? null : $clean($input['entrances'], 'entrance');
        }
        if (array_key_exists('signs', $input)) {
            $stored['signs'] = $clean($input['signs'] ?? [], 'sign');
        }
        if (array_key_exists('centre', $input)) {
            $c = $input['centre'];
            $stored['centre'] = is_array($c) && isset($c['lat'], $c['lng']) ? ['lat' => round((float) $c['lat'], 6), 'lng' => round((float) $c['lng'], 6)] : null;
        }
        $this->save($stored, $by);

        return $this->build(true);
    }

    /** Where one room is: a place of the map (or null for "not on the map"), an optional door of its own, or hidden from visitors. */
    public function placeRoom(TrainingRoom $room, array $input, User $by): array
    {
        $stored = SiteSetting::find(self::KEY)?->value ?? [];
        $rooms = is_array($stored['rooms'] ?? null) ? $stored['rooms'] : [];
        if (! empty($input['reset'])) {
            unset($rooms[$room->id]);
        } else {
            $entry = [];
            if (array_key_exists('place', $input)) {
                $entry['place'] = $input['place'];
                // A place is one room: whoever had it before goes back to "not on the map".
                foreach ($rooms as $id => $r) {
                    if ($id !== $room->id && $input['place'] && ($r['place'] ?? null) === $input['place']) {
                        $rooms[$id]['place'] = null;
                    }
                }
            } elseif (isset($rooms[$room->id]['place']) || array_key_exists('place', $rooms[$room->id] ?? [])) {
                $entry['place'] = $rooms[$room->id]['place'];
            }
            if (array_key_exists('door', $input)) {
                if ($door = $this->point($input['door'])) {
                    $entry['door'] = $door;
                }
            } elseif (isset($rooms[$room->id]['door'])) {
                $entry['door'] = $rooms[$room->id]['door'];
            }
            $entry['hidden'] = (bool) ($input['hidden'] ?? ($rooms[$room->id]['hidden'] ?? false));
            $rooms[$room->id] = $entry;
        }
        $stored['rooms'] = $rooms;
        $this->save($stored, $by);

        return $this->build(true);
    }

    private function point(mixed $p): ?array
    {
        $size = $this->map()['size'];

        return is_array($p) && count($p) === 2 && is_numeric($p[0]) && is_numeric($p[1])
            ? [max(0, min($size['w'], (int) round($p[0]))), max(0, min($size['h'], (int) round($p[1])))]
            : null;
    }

    private function save(array $value, User $by): void
    {
        SiteSetting::updateOrCreate(['key' => self::KEY], ['value' => $value, 'updated_by' => $by->id]);
        Cache::forget(self::CACHE);
    }
}
